<script setup>
import { computed, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { authLoading, firebaseUser } from '@/services/firebaseClient';
import { importTossStatement, loadPortfolioDashboard } from '@/services/portfolio';
const router = useRouter();
const file = ref(null), password = ref(''), message = ref(''), error = ref(''), importing = ref(false), loading = ref(false);
const dashboard = ref({ assets: [], transactions: [], summary: {} });
const tickerFilter = ref(''), typeFilter = ref(''), selectedAsset = ref(null), detailDialog = ref(null);
const won = (v) => Number.isFinite(Number(v)) ? `₩${Math.round(Number(v)).toLocaleString('ko-KR')}` : '—';
const quantity = (v) => Number.isFinite(Number(v)) ? Number(v).toLocaleString('ko-KR', { maximumFractionDigits: 4 }) : '—';
const date = (v) => v ? String(v).replace(/(\d{4})(\d{2})(\d{2})/, '$1.$2.$3') : '—';
const typeLabel = (v) => ({ buy: '매수', sell: '매도', dividend: '배당' }[v] ?? '기타');
const typeClass = (v) => ({ buy: 'buy', sell: 'sell', dividend: 'dividend' }[v] ?? 'unknown');
async function refresh() { if (!firebaseUser.value) return; loading.value = true; error.value = ''; try { dashboard.value = await loadPortfolioDashboard(firebaseUser.value.uid); } catch (reason) { error.value = '포트폴리오를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.'; console.error(reason); } finally { loading.value = false; } }
watch([firebaseUser, authLoading], async ([user, waiting]) => { if (waiting) return; if (!user) router.replace('/login'); else await refresh(); }, { immediate: true });
const filteredTransactions = computed(() => dashboard.value.transactions.filter((t) => (!tickerFilter.value || t.asset.ticker === tickerFilter.value) && (!typeFilter.value || t.type === typeFilter.value)).slice(0, 20));
const tickers = computed(() => dashboard.value.assets.filter((asset) => asset.ticker));
function openDetail(asset) { selectedAsset.value = asset; detailDialog.value?.showModal(); }
function closeDetail() { detailDialog.value?.close(); }
async function upload() { error.value = ''; message.value = ''; if (!file.value) { error.value = '토스 거래내역 PDF를 선택해 주세요.'; return; } importing.value = true; try { const result = await importTossStatement(firebaseUser.value, file.value, password.value); password.value = ''; file.value = null; message.value = `${result.transactionCount}건의 거래내역을 저장했습니다.`; await refresh(); if (selectedAsset.value) selectedAsset.value = dashboard.value.assets.find((asset) => asset.id === selectedAsset.value.id) ?? null; } catch (reason) { error.value = reason.message; } finally { importing.value = false; } }
</script>
<template>
<section class="mypage">
<header class="page-header"><div><p>MY PORTFOLIO</p><h1>마이페이지</h1><span>{{ firebaseUser?.email }}의 거래 원장과 보유 종목입니다.</span></div><button class="refresh" :disabled="loading" @click="refresh"><i class="pi pi-refresh" /> 새로고침</button></header>
<p v-if="error" class="notice error">{{ error }}</p><p v-if="message" class="notice success">{{ message }}</p>
<section class="summary-grid" aria-label="포트폴리오 요약"><article><small>현재 보유</small><strong>{{ dashboard.summary.currentCount ?? 0 }}<em>종목</em></strong></article><article><small>과거 보유</small><strong>{{ dashboard.summary.historicalCount ?? 0 }}<em>종목</em></strong></article><article><small>누적 실수령 배당</small><strong>{{ won(dashboard.summary.dividendTotal) }}</strong></article><article><small>최근 거래일</small><strong>{{ date(dashboard.summary.latestTransactionDate) }}</strong></article></section>
<section class="panel import-panel"><div><h2>토스 거래내역서 추가</h2><p>PDF 원본과 비밀번호는 저장하지 않고 거래 원장만 반영합니다.</p></div><form @submit.prevent="upload"><input type="file" accept="application/pdf" @change="file = $event.target.files?.[0] || null"><input v-model="password" type="password" autocomplete="current-password" placeholder="PDF 비밀번호"><button :disabled="importing">{{ importing ? '가져오는 중' : '가져오기' }}</button></form></section>
<section class="panel"><div class="section-heading"><div><h2>종목별 요약</h2><p>선택하면 전체 거래내역을 확인할 수 있습니다.</p></div><span>{{ dashboard.assets.length }}종목</span></div><div v-if="loading" class="empty">포트폴리오를 불러오는 중입니다.</div><div v-else-if="!dashboard.assets.length" class="empty">아직 거래내역이 없습니다. 토스 거래내역서를 추가해 주세요.</div><div v-else class="asset-grid"><article v-for="asset in dashboard.assets" :key="asset.id" class="asset-card"><header><div><span class="ticker">{{ asset.ticker || '미식별' }}</span><h3>{{ asset.displayName }}</h3></div><b :class="asset.portfolioPriority === 'current' ? 'current' : 'historical'">{{ asset.portfolioPriority === 'current' ? '현재 보유' : '과거 보유' }}</b></header><dl><div><dt>보유 수량</dt><dd>{{ quantity(asset.holdingShares) }}주</dd></div><div><dt>최근 거래</dt><dd>{{ date(asset.latestTransactionDate) }}</dd></div><div><dt>누적 배당</dt><dd>{{ won(asset.dividendTotal) }}</dd></div><div><dt>원장 건수</dt><dd>매수 {{ asset.transactionCounts.buy }} · 매도 {{ asset.transactionCounts.sell }} · 배당 {{ asset.transactionCounts.dividend }}</dd></div></dl><footer><button @click="openDetail(asset)">거래 상세</button><router-link v-if="asset.ticker" :to="`/thumbnail/${asset.ticker}`">썸네일 보기 <i class="pi pi-arrow-right" /></router-link></footer></article></div></section>
<section class="panel"><div class="section-heading"><div><h2>최근 거래내역</h2><p>최근 20건만 표시합니다. 종목 상세에서는 전체 원장을 볼 수 있습니다.</p></div><div class="filters"><select v-model="tickerFilter" aria-label="종목 필터"><option value="">전체 종목</option><option v-for="asset in tickers" :key="asset.id" :value="asset.ticker">{{ asset.ticker }}</option></select><select v-model="typeFilter" aria-label="거래 유형 필터"><option value="">전체 유형</option><option value="buy">매수</option><option value="sell">매도</option><option value="dividend">배당</option></select></div></div><div class="table-wrap"><table><thead><tr><th>날짜</th><th>종목</th><th>유형</th><th class="numeric">수량</th><th class="numeric">금액</th><th class="numeric">수수료</th><th class="numeric">세금</th></tr></thead><tbody><tr v-for="transaction in filteredTransactions" :key="`${transaction.asset.id}-${transaction.date}-${transaction.type}-${transaction.amount}`"><td>{{ date(transaction.date) }}</td><td><button class="asset-link" @click="openDetail(transaction.asset)">{{ transaction.asset.ticker || transaction.asset.displayName }}</button></td><td><span class="type" :class="typeClass(transaction.type)">{{ typeLabel(transaction.type) }}</span></td><td class="numeric">{{ quantity(transaction.quantity) }}</td><td class="numeric">{{ won(transaction.amount) }}</td><td class="numeric">{{ won(transaction.commission) }}</td><td class="numeric">{{ won(transaction.tax) }}</td></tr><tr v-if="!filteredTransactions.length"><td colspan="7" class="empty">표시할 거래내역이 없습니다.</td></tr></tbody></table></div></section>
<dialog ref="detailDialog" class="detail-dialog" @close="selectedAsset = null"><section v-if="selectedAsset"><header><div><p>{{ selectedAsset.ticker || '미식별 종목' }}</p><h2>{{ selectedAsset.displayName }}</h2><span :class="selectedAsset.portfolioPriority === 'current' ? 'current' : 'historical'">{{ selectedAsset.portfolioPriority === 'current' ? '현재 보유' : '과거 보유' }}</span></div><button class="close" aria-label="상세 창 닫기" @click="closeDetail">×</button></header><div class="detail-metrics"><article><small>보유 수량</small><strong>{{ quantity(selectedAsset.holdingShares) }}주</strong></article><article><small>누적 배당</small><strong>{{ won(selectedAsset.dividendTotal) }}</strong></article><article><small>거래 건수</small><strong>{{ selectedAsset.transactions.length }}건</strong></article></div><router-link v-if="selectedAsset.ticker" class="thumbnail-link" :to="`/thumbnail/${selectedAsset.ticker}`" @click="closeDetail">{{ selectedAsset.ticker }} 썸네일 페이지 바로가기 <i class="pi pi-arrow-right" /></router-link><div class="table-wrap detail-table"><table><thead><tr><th>날짜</th><th>유형</th><th class="numeric">수량</th><th class="numeric">금액</th><th class="numeric">수수료</th><th class="numeric">세금</th></tr></thead><tbody><tr v-for="transaction in selectedAsset.transactions" :key="`${transaction.date}-${transaction.type}-${transaction.amount}`"><td>{{ date(transaction.date) }}</td><td><span class="type" :class="typeClass(transaction.type)">{{ typeLabel(transaction.type) }}</span></td><td class="numeric">{{ quantity(transaction.quantity) }}</td><td class="numeric">{{ won(transaction.amount) }}</td><td class="numeric">{{ won(transaction.commission) }}</td><td class="numeric">{{ won(transaction.tax) }}</td></tr></tbody></table></div></section></dialog>
</section>
</template>
<style scoped>
.mypage{max-width:1240px;margin:24px auto 60px;color:#172033}.page-header,.section-heading,.asset-card header,.asset-card footer,.detail-dialog header{display:flex;justify-content:space-between;align-items:center;gap:16px}.page-header{margin-bottom:22px}.page-header p,.detail-dialog header p{margin:0;color:#2563eb;font-size:11px;font-weight:800;letter-spacing:.14em}.page-header h1,.detail-dialog h2{margin:6px 0;font-size:30px;letter-spacing:-.05em}.page-header span,.section-heading p,.import-panel p{color:#697589;font-size:13px}.refresh,.import-panel button,.asset-card footer button{border:1px solid #cbd5e1;border-radius:8px;background:#fff;padding:10px 13px;font:inherit;cursor:pointer}.notice{padding:12px 14px;border-radius:10px}.notice.error{background:#fef2f2;color:#b91c1c}.notice.success{background:#ecfdf5;color:#047857}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.summary-grid article,.panel,.asset-card{border:1px solid #e2e8f0;border-radius:16px;background:#fff}.summary-grid article{padding:19px}.summary-grid small,.detail-metrics small{display:block;color:#697589;font-size:12px;font-weight:700}.summary-grid strong{display:block;margin-top:10px;font-size:25px;letter-spacing:-.05em}.summary-grid em{margin-left:3px;color:#697589;font-size:12px;font-style:normal;font-weight:500}.panel{margin-top:18px;padding:22px}.panel h2{margin:0;font-size:18px}.import-panel{display:flex;justify-content:space-between;gap:20px;align-items:center}.import-panel p{margin:7px 0 0}.import-panel form{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}.import-panel input{max-width:185px;padding:10px;border:1px solid #cbd5e1;border-radius:8px;font:inherit}.import-panel button{background:#2563eb;border-color:#2563eb;color:#fff}.section-heading{margin-bottom:18px}.section-heading p{margin:6px 0 0}.section-heading>span{color:#697589;font-size:13px}.asset-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:12px}.asset-card{padding:17px}.ticker{font-size:12px;font-weight:800;color:#2563eb}.asset-card h3{margin:5px 0 0;font-size:17px}.current,.historical,.type{display:inline-block;padding:4px 7px;border-radius:6px;font-size:11px;font-weight:800}.current,.type.buy{background:#dbeafe;color:#1d4ed8}.historical,.type.sell{background:#ede9fe;color:#6d28d9}.type.dividend{background:#d1fae5;color:#047857}.type.unknown{background:#e2e8f0;color:#475569}.asset-card dl{margin:18px 0;display:grid;grid-template-columns:1fr 1fr;gap:13px}.asset-card dl div:last-child{grid-column:1/-1}.asset-card dt{color:#697589;font-size:11px}.asset-card dd{margin:5px 0 0;font-size:13px;font-weight:700}.asset-card footer{padding-top:14px;border-top:1px solid #e2e8f0}.asset-card footer button{padding:7px 9px;font-size:12px}.asset-card footer a,.thumbnail-link{color:#2563eb;text-decoration:none;font-size:12px;font-weight:700}.filters{display:flex;gap:8px}.filters select{padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;font:inherit;font-size:12px}.table-wrap{overflow:auto;border:1px solid #e2e8f0;border-radius:10px}table{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap}th,td{padding:12px;text-align:left;border-bottom:1px solid #e2e8f0}th{background:#f8fafc;color:#697589;font-size:11px}.numeric{text-align:right}.asset-link{border:0;background:none;color:#2563eb;padding:0;font:inherit;font-weight:800;cursor:pointer}.empty{text-align:center;color:#697589;padding:28px}.detail-dialog{width:min(900px,calc(100vw - 32px));max-height:85vh;border:0;border-radius:18px;padding:0;box-shadow:0 25px 70px #0f172a55}.detail-dialog::backdrop{background:#0f172a88}.detail-dialog section{padding:24px}.detail-dialog header{align-items:flex-start}.detail-dialog h2{font-size:23px}.close{border:0;background:none;font-size:30px;line-height:1;cursor:pointer}.detail-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0}.detail-metrics article{padding:14px;border-radius:10px;background:#f8fafc}.detail-metrics strong{display:block;margin-top:6px;font-size:18px}.thumbnail-link{display:block;margin-bottom:16px}.detail-table{max-height:420px}@media(max-width:760px){.mypage{margin:12px auto 36px}.page-header,.import-panel,.section-heading{align-items:flex-start;flex-direction:column}.summary-grid{grid-template-columns:1fr 1fr}.import-panel form{justify-content:flex-start}.asset-grid{grid-template-columns:1fr}.filters{width:100%}.filters select{flex:1;min-width:0}.detail-metrics{grid-template-columns:1fr}.panel{padding:16px}}
</style>
